const char* hold_text(std::string value) {
    std::string& slot = text_ring[text_ring_index++ % text_ring.size()];
    slot = std::move(value);
    return slot.c_str();
}

std::string text_or_empty(const char* value) {
    return value ? std::string(value) : std::string();
