param(
    [string]$Root = ".",
    [string]$Uxb = ""
)
$ErrorActionPreference = "Continue"
$Root = (Resolve-Path $Root).Path
Set-Location $Root
if ([string]::IsNullOrWhiteSpace($Uxb)) { $Uxb = Join-Path $Root "bin\uxb.exe" }
if (!(Test-Path $Uxb)) { throw "uxb.exe bulunamadi: $Uxb" }

$reportDir = Join-Path $Root "reports\yama6_runtime\mir_strict"
New-Item -ItemType Directory -Force $reportDir | Out-Null

$cases = @(
    @{name="event_input"; source="xtestx\yama6_runtime\event_input_yama6.uxb"; required=@("EVENT_INPUT","42")},
    @{name="tasktable_all_kinds"; source="xtestx\yama6_runtime\tasktable_all_kinds_yama6.uxb"; required=@("PIPE_RUN","3","THREAD_RUN","PARALEL_RUN")},
    @{name="slot_off"; source="xtestx\yama6_runtime\slot_off_yama6.uxb"; required=@("DONE"); forbidden=@("SHOULD_NOT_PRINT")},
    @{name="shell_capture"; source="xtestx\yama6_runtime\shell_capture_yama6.uxb"; required=@("SHELL_OK","0")}
)

$results = @()
$fail = 0
foreach ($case in $cases) {
    $src = Join-Path $Root $case.source
    $stdout = Join-Path $reportDir ($case.name + ".stdout.txt")
    $stderr = Join-Path $reportDir ($case.name + ".stderr.txt")
    $program = Join-Path $reportDir ($case.name + ".program_output.txt")
    $execJson = Join-Path $reportDir ($case.name + ".mir_exec_result.json")
    foreach ($p in @($stdout,$stderr,$program,$execJson)) { if (Test-Path $p) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue } }

    $args = @("--source", $src, "--execmem", "--interpreter-backend", "MIR", "--mir-verify", "--console-mode", "direct", "--stdout-out", $stdout, "--stderr-out", $stderr, "--program-output-out", $program, "--mir-exec-result-json-out", $execJson)
    & $Uxb @args 1> (Join-Path $reportDir ($case.name + ".process.stdout.txt")) 2> (Join-Path $reportDir ($case.name + ".process.stderr.txt"))
    $code = $LASTEXITCODE
    $combined = ""
    foreach ($p in @($stdout,$stderr,$program,$execJson,(Join-Path $reportDir ($case.name + ".process.stdout.txt")),(Join-Path $reportDir ($case.name + ".process.stderr.txt")))) {
        if (Test-Path $p) { $combined += "`n" + (Get-Content $p -Raw) }
    }

    $ok = ($code -eq 0)
    $checks = @{}
    foreach ($r in $case.required) {
        $hit = ($combined -match [regex]::Escape($r))
        $checks["required:$r"] = $hit
        if (!$hit) { $ok = $false }
    }
    if ($case.ContainsKey("forbidden")) {
        foreach ($f in $case.forbidden) {
            $hit = ($combined -match [regex]::Escape($f))
            $checks["forbidden:$f"] = (!$hit)
            if ($hit) { $ok = $false }
        }
    }

    if (!$ok) { $fail += 1 }
    $results += [pscustomobject]@{
        name=$case.name
        source=$case.source
        returncode=$code
        status=if($ok){"PASS"}else{"FAIL"}
        checks=$checks

