    DrawTextEx(uxFonts[handle], text,
               (Vector2){ (float)(x - uxCameraX), (float)(y - uxCameraY) },
               (float)size, (float)spacing,
               (Color){ (unsigned char)r, (unsigned char)g,
                        (unsigned char)b, (unsigned char)a });
}

