1	// uXBasic uxcollections.dll - GLib-backed collection wrapper
2	// Provides List/Stack/Queue/Deque/Dict/Set/Tree/Node primitives as DLL calls.
3	// Graph and DataFrame are intentionally separate modules: uxgraph (igraph) and uxdataframe (DuckDB/Arrow).
4	#include <glib.h>
5	#include <stdint.h>
6	#include <stdlib.h>
7	#include <string.h>
8	#include <stdio.h>
9	
10	#if defined(_WIN32)
11	#include <windows.h>
12	#define UX_EXPORT __declspec(dllexport)
13	#else
14	#define UX_EXPORT
15	#endif
16	
17	typedef enum { UXV_NULL=0, UXV_I64=1, UXV_F64=2, UXV_STR=3, UXV_PTR=4 } UXVKind;
18	typedef struct UXValue { UXVKind kind; int64_t i64; double f64; void* ptr; char* str; } UXValue;
19	
20	typedef enum { C_LIST=1, C_STACK=2, C_QUEUE=3, C_DEQUE=4, C_DICT=5, C_SET=6, C_TREE=7, C_NODE=8 } UXCKind;
21	typedef struct UXCollection { UXCKind kind; void* obj; } UXCollection;
22	
23	static UXValue* val_new_null(void){ UXValue* v=(UXValue*)g_malloc0(sizeof(UXValue)); return v; }
24	static UXValue* val_new_i64(int64_t x){ UXValue* v=val_new_null(); v->kind=UXV_I64; v->i64=x; return v; }
25	static UXValue* val_new_f64(double x){ UXValue* v=val_new_null(); v->kind=UXV_F64; v->f64=x; return v; }
26	static UXValue* val_new_ptr(void* x){ UXValue* v=val_new_null(); v->kind=UXV_PTR; v->ptr=x; return v; }
27	static UXValue* val_new_str(const char* s){ UXValue* v=val_new_null(); v->kind=UXV_STR; v->str=g_strdup(s?s:""); return v; }
28	static void val_free(gpointer p){ UXValue* v=(UXValue*)p; if(!v) return; if(v->kind==UXV_STR) g_free(v->str); g_free(v); }
29	static UXCollection* coll_new(UXCKind k, void* obj){ UXCollection* c=(UXCollection*)g_malloc0(sizeof(UXCollection)); c->kind=k; c->obj=obj; return c; }
30	static UXCollection* as_coll(void* h, UXCKind k){ UXCollection* c=(UXCollection*)h; if(!c || c->kind!=k) return NULL; return c; }
31	static GPtrArray* as_list(void* h){ UXCollection* c=as_coll(h,C_LIST); return c?(GPtrArray*)c->obj:NULL; }
32	static GQueue* as_queue_kind(void* h, UXCKind k){ UXCollection* c=as_coll(h,k); return c?(GQueue*)c->obj:NULL; }
33	static GHashTable* as_hash(void* h, UXCKind k){ UXCollection* c=as_coll(h,k); return c?(GHashTable*)c->obj:NULL; }
34	static GTree* as_tree(void* h){ UXCollection* c=as_coll(h,C_TREE); return c?(GTree*)c->obj:NULL; }
35	static int str_cmp(gconstpointer a, gconstpointer b, gpointer user_data){ (void)user_data; return g_strcmp0((const char*)a,(const char*)b); }
36	static void node_destroy(gpointer data){ val_free(data); }
37	
38	UX_EXPORT int uxcollections_version(void){ return 1; }
39	UX_EXPORT int uxcollections_uses_glib(void){ return 1; }
40	
41	// ---------- LIST ----------
42	UX_EXPORT void* uxc_list_new(void){ return coll_new(C_LIST, g_ptr_array_new_with_free_func(val_free)); }
43	UX_EXPORT void uxc_list_free(void* h){ UXCollection* c=as_coll(h,C_LIST); if(!c) return; g_ptr_array_free((GPtrArray*)c->obj, TRUE); g_free(c); }
44	UX_EXPORT int64_t uxc_list_count(void* h){ GPtrArray* a=as_list(h); return a?(int64_t)a->len:0; }
45	UX_EXPORT void uxc_list_clear(void* h){ GPtrArray* a=as_list(h); if(a) g_ptr_array_set_size(a,0); }
46	UX_EXPORT void uxc_list_push_i64(void* h,int64_t x){ GPtrArray* a=as_list(h); if(a) g_ptr_array_add(a,val_new_i64(x)); }
47	UX_EXPORT void uxc_list_push_f64(void* h,double x){ GPtrArray* a=as_list(h); if(a) g_ptr_array_add(a,val_new_f64(x)); }
48	UX_EXPORT void uxc_list_push_str(void* h,const char* s){ GPtrArray* a=as_list(h); if(a) g_ptr_array_add(a,val_new_str(s)); }
49	UX_EXPORT int uxc_list_remove_at(void* h,int64_t idx){ GPtrArray* a=as_list(h); if(!a||idx<0||idx>=(int64_t)a->len) return 0; g_ptr_array_remove_index(a,(guint)idx); return 1; }
50	static UXValue* list_val(void* h,int64_t idx){ GPtrArray* a=as_list(h); if(!a||idx<0||idx>=(int64_t)a->len) return NULL; return (UXValue*)g_ptr_array_index(a,(guint)idx); }
51	UX_EXPORT int64_t uxc_list_get_i64(void* h,int64_t idx){ UXValue* v=list_val(h,idx); if(!v) return 0; if(v->kind==UXV_I64) return v->i64; if(v->kind==UXV_F64) return (int64_t)v->f64; return 0; }
52	UX_EXPORT double uxc_list_get_f64(void* h,int64_t idx){ UXValue* v=list_val(h,idx); if(!v) return 0; if(v->kind==UXV_F64) return v->f64; if(v->kind==UXV_I64) return (double)v->i64; return 0; }
53	UX_EXPORT const char* uxc_list_get_str(void* h,int64_t idx){ UXValue* v=list_val(h,idx); if(!v) return ""; if(v->kind==UXV_STR) return v->str?v->str:""; return ""; }
