input.command:
$path = "C:\Users\mete\.claude\projects\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\760ce433-ff72-46c7-8b20-30eed40f7a8c.jsonl"
$outPath = "$env:TEMP\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\760ce433-ff72-46c7-8b20-30eed40f7a8c\scratchpad\real_user_messages.txt"
New-Item -ItemType Directory -Force -Path (Split-Path $outPath) | Out-Null
$count = 0
$writer = [System.IO.StreamWriter]::new($outPath, $false, [System.Text.Encoding]::UTF8)
Get-Content $path | ForEach-Object {
  $line = $_
  if ($line -notmatch '"type":"user"') { return }
  try { $o = $line | ConvertFrom-Json -ErrorAction Stop } catch { return }
  if ($o.type -ne "user") { return }
  $msg = $o.message
  if (-not $msg) { return }
  $content = $msg.content
  $isRealText = $false
  $textParts = @()
  if ($content -is [string]) {
    $isRealText = $true
    $textParts += $content
  } elseif ($content -is [System.Collections.IEnumerable]) {
    $hasToolResult = $false
    foreach ($block in $content) {
      if ($block.type -eq "tool_result") { $hasToolResult = $true }
      if ($block.type -eq "text") { $textParts += $block.text }
    }
    if (-not $hasToolResult -and $textParts.Count -gt 0) { $isRealText = $true }
  }
  if ($isRealText) {
    $ts = $o.timestamp
    $joined = ($textParts -join " ")
    if ($joined.Trim().Length -gt 0) {
      $writer.WriteLine("=== $ts ===")
      $writer.WriteLine($joined)
      $writer.WriteLine("")
      $count++
    }
  }
}
$writer.Close()
Write-Output "Found $count real user text messages"
(Get-Item $outPath).Length

