Set-Location "C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
# block-IF version of t2 (single-line IF..ELSE prints both branches in AST and MIR -- separate finding)
$t = (Get-Content "$sp\u64_t2.uxb" -Raw)
$t = $t -replace 'IF big > 9223372036854775807 THEN PRINT "gt-i64max" ELSE PRINT "le"', "IF big > 9223372036854775807 THEN`r`nPRINT `"gt-i64max`"`r`nELSE`r`nPRINT `"le`"`r`nEND IF"
$t = $t -replace 'IF big >= big THEN PRINT "ge" ELSE PRINT "lt"', "IF big >= big THEN`r`nPRINT `"ge`"`r`nELSE`r`nPRINT `"lt`"`r`nEND IF"
$t = $t -replace 'IF small < big THEN PRINT "small<big" ELSE PRINT "small>=big"', "IF small < big THEN`r`nPRINT `"small<big`"`r`nELSE`r`nPRINT `"small>=big`"`r`nEND IF"
Set-Content "$sp\u64_t3.uxb" $t -Encoding utf8
function Norm([string]$s) { (($s -replace "`r","") -split "`n" | Where-Object { $_ -notmatch '^INFO|^\s*$' }) -join " | " }
foreach ($f in @('u64_probe','u64_t3')) {
  "== $f"
  "AST : " + (Norm ((& .\bin\uxb.exe run "$sp\$f.uxb" 2>&1) -join "`n"))
  "MIR : " + (Norm ((& .\bin\uxb.exe run "$sp\$f.uxb" --interpreter-backend MIR 2>&1) -join "`n"))
  foreach ($mode in @(@("x64", @()), @("AST-x64", @("--x64-mode","AST")))) {
    $o = (& .\bin\uxb.exe bld "$sp\$f.uxb" @($mode[1]) -o "out\u64s_$($mode[0]).exe" 2>&1) -join "`n"
    $m = [regex]::Match($o, "build tamamlandi: (.+)")
    if ($m.Success) { "$($mode[0]) : " + (Norm ((& $m.Groups[1].Value.Trim() 2>&1) -join "`n")) } else { "$($mode[0]) BUILDFAIL: " + (Norm $o) }
  }
}

