$f = 'src\codegen\x64\mir_x64_context.fbs'
$full = (Resolve-Path $f).Path
$bytes = [System.IO.File]::ReadAllBytes($full)
$bom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
$enc = New-Object System.Text.UTF8Encoding($false)
$off = $(if ($bom) {3} else {0})
$text = $enc.GetString($bytes, $off, $bytes.Length - $off)
$nl = $(if ($text.Contains("`r`n")) { "`r`n" } else { "`n" })
$widthOf = @{ 'b' = 1; 'w' = 2; 'd' = 4; 'q' = 8 }
$count = 0
foreach ($kind in @('load','store')) {
  foreach ($w in @('b','w','d','q')) {
    $label = "    MIRX64EmitHelperLine cg, `".mem_${kind}${w}_resolve:`""
    $ins = "    MIRX64EmitHelperLine cg, `"    mov qword [rel __uxb_memref_width], $($widthOf[$w])`""
    $needle = $label + $nl
    if ($text.Contains($needle) -and -not $text.Contains($needle + $ins)) { $text = $text.Replace($needle, $needle + $ins + $nl); $count++ }
    else { "MISS ${kind}${w}" }
  }
}
# copy / fill / peeks / pokes: width comes from a register that is live at the label
$sites = @(
  @('.mem_copy_mode_native_or_auto:', 'mov qword [rel __uxb_memref_width], r8'),
  @('.mem_fill_mode_resolve:', 'mov qword [rel __uxb_memref_width], r11'),
  @('.mem_peeks_resolve:', 'mov qword [rel __uxb_memref_width], rdx')
)
foreach ($s in $sites) {
  $label = "    MIRX64EmitHelperLine cg, `"$($s[0])`""
  $ins = "    MIRX64EmitHelperLine cg, `"    $($s[1])`""
  $needle = $label + $nl
  if ($text.Contains($needle) -and -not $text.Contains($needle + $ins)) { $text = $text.Replace($needle, $needle + $ins + $nl); $count++ } else { "MISS $($s[0])" }
}
$out = $enc.GetBytes($text); if ($bom) { $out = [byte[]](0xEF,0xBB,0xBF) + $out }
[System.IO.File]::WriteAllBytes($full, $out)
"inserted width setup at $count sites"
Select-String -Path $f -Pattern 'mem_poke.*resolve|mem_pokes' | Select-Object -First 5 | ForEach-Object { "{0}: {1}" -f $_.LineNumber, $_.Line.Trim() }

