param([string]$Root, [string]$Before, [string]$After, [string]$OutFile, [string]$DirsCsv)
$Dirs = $DirsCsv -split ","
$ErrorActionPreference = "Continue"
Set-Location $Root
function Run-One([string]$exe, [string[]]$argList, [int]$timeoutSec) {
  $psi = New-Object System.Diagnostics.ProcessStartInfo
  $psi.FileName = $exe
  $psi.Arguments = ($argList | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) -join ' '
  $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
  $p = [System.Diagnostics.Process]::Start($psi)
  $so = $p.StandardOutput.ReadToEndAsync(); $se = $p.StandardError.ReadToEndAsync()
  if (-not $p.WaitForExit($timeoutSec * 1000)) { try { $p.Kill() } catch {}; return "TIMEOUT" }
  $txt = $so.Result + $se.Result
  return ((($txt -replace "`r","") -replace 'build[/\\]\d\d_\d\d_\d{4}_\d\d_\d\d_\d\d','build/TS') -split "`n" | Where-Object { $_ -notmatch '^INFO:|^\s*$' }) -join "`n"
}
$files = foreach ($d in $Dirs) { Get-ChildItem (Join-Path $Root $d) -Recurse -File -Filter *.uxb -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '\\expected\\|\\out\\|\\build\\' } }
$total = 0; $diff = 0
"START $(Get-Date -Format s) files=$($files.Count)" | Set-Content $OutFile -Encoding utf8
foreach ($f in $files) {
  foreach ($mode in @(@("AST", @()), @("MIR", @("--interpreter-backend","MIR")))) {
    $args1 = @("run", $f.FullName) + $mode[1]
    $b = Run-One $Before $args1 20
    $a = Run-One $After $args1 20
    $total++
    if ($a -ne $b) {
      $diff++
      "DIFF [$($mode[0])] $($f.FullName.Substring($Root.Length+1))" | Add-Content $OutFile -Encoding utf8
      "  BEFORE: " + (($b -split "`n" | Select-Object -First 4) -join " | ") | Add-Content $OutFile -Encoding utf8
      "  AFTER : " + (($a -split "`n" | Select-Object -First 4) -join " | ") | Add-Content $OutFile -Encoding utf8
    }
  }
}
"DONE $(Get-Date -Format s) runs=$total diffs=$diff" | Add-Content $OutFile -Encoding utf8

