 "e5_nested_break" = "DIM a(3) AS I32`nDIM v AS I32`nDIM i AS I32`na(0)=1 : a(1)=2 : a(2)=3 : a(3)=4`nFOR EACH v, i IN a`n    IF v = 3 THEN`n        EXIT FOR`n    END IF`n    PRINT v`nNEXT`nPRINT ""son""`n";
 "e6_mutate_in_loop" = "DIM l AS LIST`nDIM v AS I32`nLISTADD(l, 1)`nLISTADD(l, 2)`nFOR EACH v IN l`n    PRINT v`n    IF v = 1 THEN LISTADD(l, 3)`nNEXT`nPRINT LISTLEN(l)`n";
 "e7_str_array" = "DIM a(1) AS STRING`nDIM s AS STRING`na(0) = ""x""`na(1) = ""y""`nFOR EACH s IN a`n    PRINT s`nNEXT`n";
 "e8_float_array" = "DIM a(1) AS F64`nDIM f AS F64`na(0) = 1.5`na(1) = 2.5`nFOR EACH f IN a`n    PRINT f`nNEXT`n"
}
foreach ($k in $progs.Keys) { [IO.File]::WriteAllText("$sp\it\$k.uxb", $progs[$k], $enc) }
function NativeRunBin($f, $extra=@()) {
  $o = (.\bin\uxb.exe bld $f @extra -o "$sp\probe_o.exe" 2>&1) -join "`n"
  $m = [regex]::Match($o, "build tamamlandi: (.+)")
  if ($m.Success) { $pr = Start-Process -FilePath $m.Groups[1].Value.Trim() -NoNewWindow -PassThru -RedirectStandardOutput "$sp\probe_out.txt" -RedirectStandardError "$sp\probe_err.txt"; if (-not $pr.WaitForExit(20000)) { $pr.Kill(); "TIMEOUT" } else { ((Get-Content "$sp\probe_out.txt") + (Get-Content "$sp\probe_err.txt") | Where-Object { $_ }) -join "|" } } else { $e = (($o -split "`n" | Where-Object { $_ -match "ERROR" } | Select-Object -First 1)) -replace 'ERROR: ',''; "BUILDFAIL: " + $e.Substring(0,[Math]::Min(80,$e.Length)) }
}
foreach ($k in $progs.Keys) {
  $f = "$sp\it\$k.uxb"
  Write-Host ("{0,-18} AST[{1}] MIR[{2}] x64[{3}] LEG[{4}]" -f $k, ((.\bin\uxb.exe run $f 2>&1 | Select-Object -Skip 1 | Where-Object { $_ -notmatch 'INFO' }) -join "|"), ((.\bin\uxb.exe run $f --interpreter-backend MIR 2>&1 | Select-Object -Skip 1 | Where-Object { $_ -notmatch 'INFO' }) -join "|"), (NativeRunBin $f), (NativeRunBin $f @("--x64-mode","AST")))
}

