1	param(
2	    [string]$Root = '',
3	    [switch]$Force,
4	    [switch]$Release,
5	    [switch]$Debug,
6	    [switch]$SkipX86
7	)
8	$ErrorActionPreference='Stop'
9	if ($Release -and $Debug) { throw '-Release ve -Debug birlikte kullanilamaz.' }
10	$releaseMode = -not $Debug
11	# YAMA: host compiler build is x64-only by default. Set UXB_BUILD_X86=1 to opt in.
12	if ($env:UXB_BUILD_X86 -ne '1') { $SkipX86 = $true }
13	function Resolve-UxbRoot([string]$Start) {
14	    if ([string]::IsNullOrWhiteSpace($Start)) { $Start=$PSScriptRoot }
15	    $p=(Resolve-Path $Start).Path
16	    while ($true) {
17	        if ((Test-Path (Join-Path $p 'src\main.bas')) -and (Test-Path (Join-Path $p 'compiler'))) { return $p }
18	        if (Test-Path (Join-Path $p 'uxb\src\main.bas')) { return (Join-Path $p 'uxb') }
19	        $parent=Split-Path $p -Parent; if ($parent -eq $p) { throw "uXBasic root bulunamadi: $Start" }; $p=$parent
20	    }
21	}
22	function Get-PeMachine([string]$Path) {
23	    $bytes=[IO.File]::ReadAllBytes($Path); $pe=[BitConverter]::ToInt32($bytes,0x3c); $m=[BitConverter]::ToUInt16($bytes,$pe+4)
24	    if ($m -eq 0x8664) { return 'x64' }; if ($m -eq 0x014c) { return 'x86' }; return ('0x{0:X4}' -f $m)
25	}
26	function Invoke-FbcBuild([string]$Fbc,[string]$Source,[string]$Out,[string]$Expected,[string]$Log,[switch]$ReleaseMode) {
27	    $generator=if($Expected -eq 'x64'){'gas64'}else{'gas'}
28	    $args=@('-v','-lang','fb','-gen',$generator,'-w','all','-exx','-mt')
29	    if ($ReleaseMode) { $args += @('-O','2','-strip') } else { $args += '-g' }
30	    $args += @('-x',$Out,$Source)
31	    "FBC=$Fbc`r`nSOURCE=$Source`r`nOUTPUT=$Out`r`nARGS=$($args -join ' ')`r`n" | Set-Content $Log -Encoding UTF8
32	    $timer=[Diagnostics.Stopwatch]::StartNew()
33	    Write-Host "FBC_BUILD_START arch=$Expected generator=$generator source=$Source"
34	    Push-Location (Split-Path $Source -Parent)
35	    $savedErrorActionPreference=$ErrorActionPreference
36	    try {
37	        # fbc/gcc writes warnings to stderr. Capture the complete diagnostic and
38	        # decide from its exit code instead of aborting the still-running build.
39	        $ErrorActionPreference='Continue'
40	        $o=@(& $Fbc @args 2>&1)
41	        $rc=$LASTEXITCODE
42	    } finally {
43	        $ErrorActionPreference=$savedErrorActionPreference
44	        Pop-Location
45	    }
