function Run-One([string]$exe, [string]$src, [string]$tag) {
  $args2 = @("mir", $src)
  foreach ($k in $kinds.Keys) {
    $path = Join-Path $Tmp "$tag.$k.json"
    if (Test-Path $path) { [IO.File]::Delete($path) }
    $args2 += @($kinds[$k], $path)
  }
  $psi = New-Object System.Diagnostics.ProcessStartInfo
  $psi.FileName = $exe
  $psi.Arguments = ($args2 | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) -join ' '
  $psi.RedirectStandardOutput = $true; $psi.RedirectStandardError = $true; $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
  $p = [System.Diagnostics.Process]::Start($psi)
  $so = $p.StandardOutput.ReadToEndAsync(); $se = $p.StandardError.ReadToEndAsync()
  if (-not $p.WaitForExit(120000)) { try { $p.Kill() } catch {}; return "TIMEOUT" }
  $txt = ((($so.Result + $se.Result) -replace "`r","") -replace 'build[/\\]\d\d_\d\d_\d{4}_\d\d_\d\d_\d\d','build/TS') -split "`n" | Where-Object { $_ -notmatch '^INFO:|^\s*$' }
  $hs = foreach ($k in ($kinds.Keys | Sort-Object)) { $path = Join-Path $Tmp "$tag.$k.json"; if (Test-Path $path) { "$k=" + (Get-FileHash $path).Hash.Substring(0,10) } else { "$k=none" } }
  return "exit=$($p.ExitCode) | " + ($txt -join " / ") + " | " + ($hs -join " ")
}
$files = Get-ChildItem (Join-Path $Root "tests") -Recurse -File -Filter *.uxb -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '\\expected\\|\\out\\|\\build\\' }
$total = 0; $diff = 0
"START $(Get-Date -Format s) files=$($files.Count)" | Set-Content $OutFile -Encoding utf8
foreach ($f in $files) {
  $b = Run-One $Before $f.FullName "b"
  $a = Run-One $After $f.FullName "a"
  $total++
  if ($a -ne $b) {
    $diff++
    "DIFF $($f.FullName.Substring($Root.Length+1))" | Add-Content $OutFile -Encoding utf8
    "  BEFORE: " + $b.Substring(0, [Math]::Min(420, $b.Length)) | Add-Content $OutFile -Encoding utf8
    "  AFTER : " + $a.Substring(0, [Math]::Min(420, $a.Length)) | Add-Content $OutFile -Encoding utf8
  }
}
"DONE $(Get-Date -Format s) files=$total diffs=$diff" | Add-Content $OutFile -Encoding utf8
'@
