  $raw = [System.IO.File]::ReadAllText($p)
  $nl = if ($raw.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $raw -split "`r?`n", -1
  foreach ($k in $map.Keys) {
    $i = [int]$k - 1
    $from = $map[$k][0]; $to = $map[$k][1]
    if (-not $lines[$i].Contains($from)) { throw "$file satir $k beklenen '$from' yok: $($lines[$i])" }
    $lines[$i] = $lines[$i].Replace($from, $to)
  }
  [System.IO.File]::WriteAllText($p, ($lines -join $nl), (New-Object System.Text.UTF8Encoding($false)))
}
