$bas = [System.IO.File]::ReadAllText((Resolve-Path .\libsx\uxsdl3\uxsdl3.bas).Path)
$ms = [regex]::Matches($bas, '(?im)^(FUNCTION|SUB)\s+(\w+)\s*\(([^)]*)\)(?:\s+AS\s+(\w+))?')
$rules = [ordered]@{
  "Çekirdek ve bilgi" = '^(Init|Quit|InitSubSystem|QuitSubSystem|WasInit|AdapterVersion|RuntimeVersion|Revision|GetPlatform|LastError|ClearError|SetAppMetadata|GetAppMetadata|SetHint|GetHint)$'
  "Ekranlar (display) ve video sürücüsü" = '^(Display\w*|PrimaryDisplay|VideoDriver\w*|CurrentVideoDriver|ScreenSaverEnabled|SetScreensaver|SystemTheme|GetDisplay\w+)$'
  "Metin girişi ve pano" = '(Clipboard|TextInput)'
  "Pencere" = '(Window|^ShowWindow$|^HideWindow$)'
  "Ses (sound, ton, aygıt)" = '^(Sound\w*|LoadSound|PlaySound|StopSound|UnloadSound|PauseSound|ResumeSound|IsSound\w+|SetSound\w+|GetSound\w+|CreateTone|SaveSoundWAV|SetMasterVolume|GetMasterVolume|Audio\w+|CurrentAudioDriver)$'
  "Doku (texture)" = '(Texture)'
  "Çizici (renderer)" = '(Render|Renderer|PackRGBA|Unpack\w)'
  "Joystick / gamepad / sanal aygıt" = '^(Joystick\w*|Gamepad\w*|OpenJoystick|CloseJoystick|OpenGamepad|CloseGamepad|IsGamepad|AddGamepadMapping|AttachVirtual\w+|DetachVirtual|SetVirtual\w+)$'
  "Klavye, fare, imleç ve olaylar" = '^(PumpEvents|ShouldQuit|ClearQuit|KeyDown|Key\w+|LastKey|Mouse\w+|GetMouse\w+|Push\w+|FlushEvents|TakeDeviceEvents|Drop\w+|TakeDrop|ScancodeFromName|ScancodeFromKey|GetScancodeName|GetModState|SetModState|HasMouse|HasKeyboard|HasScreenKeyboard|WarpMouse\w+|CaptureMouse|GlobalMouse|ShowCursor|HideCursor|CursorVisible|SetSystemCursor|Touch\w+|KeyboardCount)$'
  "Zaman ve takvim" = '^(GetTicks\w*|Delay\w*|Perf\w+|CurrentTimeNS|DatePart|DaysInMonth|DayOfYear)$'
  "Dosya sistemi" = '^(BasePath|PrefPath|CurrentDirectory|CreateDirectory|Path\w+|RemovePath|RenamePath|CopyFile|ListDirectory|ListItem)$'
  "Sistem, güç, yerel ayar" = '^(CPU\w+|SystemRAMMB|Power\w+|Locale\w+|IsTablet|IsTV)$'
}
$groups = @{}; foreach ($k in $rules.Keys) { $groups[$k] = New-Object System.Collections.Generic.List[string] }
$other = New-Object System.Collections.Generic.List[string]
foreach ($m in $ms) {
  $name = $m.Groups[2].Value
  $params = ($m.Groups[3].Value -replace '\s+AS\s+', ' AS ').Trim()
  $ret = $m.Groups[4].Value
  $sig = if ($m.Groups[1].Value.ToUpper() -eq 'SUB') { "SUB $name($params)" } else { "FUNCTION $name($params) AS $ret" }
  $placed = $false
  foreach ($k in $rules.Keys) { if ($name -match $rules[$k]) { $groups[$k].Add($sig); $placed = $true; break } }
  if (-not $placed) { $other.Add($sig) }
}
"toplam: " + $ms.Count + " diger: " + $other.Count
($other | Select-Object -First 30) -join "`n"
foreach ($k in $rules.Keys) { "{0}: {1}" -f $k, $groups[$k].Count }
$sc = "C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\760ce433-ff72-46c7-8b20-30eed40f7a8c\scratchpad"
$sb = New-Object System.Text.StringBuilder
foreach ($k in $rules.Keys) {
  [void]$sb.AppendLine("### $k"); [void]$sb.AppendLine("")
  [void]$sb.AppendLine('```basic')
  foreach ($s in ($groups[$k] | Sort-Object)) { [void]$sb.AppendLine($s) }
  [void]$sb.AppendLine('```'); [void]$sb.AppendLine("")
}
if ($other.Count -gt 0) { [void]$sb.AppendLine("### Diğer"); [void]$sb.AppendLine(""); [void]$sb.AppendLine('```basic'); foreach ($s in ($other | Sort-Object)) { [void]$sb.AppendLine($s) }; [void]$sb.AppendLine('```') }
[System.IO.File]::WriteAllText("$sc\api_index.md", $sb.ToString(), (New-Object System.Text.UTF8Encoding($false)))

