// Generic controlled-error exit for emitted x64 code: prints a message (the
// TR/EN diagnostic text the compiler already generates at the call site) and
// exits cleanly with a non-zero code. Deliberately NOT called by any of the
// collection accessors above -- only the emitter calls this, after it has
// already checked a 0/-1 status for itself. Uses std::exit (unwinds C++
// destructors, flushes streams), not std::abort (SIGABRT / no cleanup), since
// this is an ordinary, expected language-level runtime error, not a fatal
// internal-invariant violation.
UXB_RT_API const char* UXB_RT_CDECL __uxb_rt_str_f64(double value) {
    // S-047 (Codex): the original "%g" here truncated to 6 significant
    // digits, so distinct DICT/SET F64 keys like 1.0000001 and 1.0000002
    // both stringified to "1" and silently collided (the second DICTSET
    // overwrote the first key's value instead of creating a second entry).
    // std::to_chars produces the *shortest decimal string that round-trips
    // back to the exact same double* (no fixed digit-count truncation), so
    // two distinct doubles can never collapse to the same key text. This is
    // also the same class of algorithm modern language runtimes (including,
    // very likely, FreeBASIC's own Str()) use for default float-to-string
    // conversion, so it should match the AST/MIR interpreters' key text for
    // ordinary values -- exact byte-for-byte parity in every exponent/
    // extreme-value corner case is not independently verified here.
    // Normalize negative zero to "0": -0.0 and 0.0 compare equal and should
    // never be distinguishable as DICT/SET keys.
    if (value == 0.0) return hold_text(std::string("0"));
    char buf[64];
    auto result = std::to_chars(buf, buf + sizeof(buf), value);
    return hold_text(std::string(buf, result.ptr));
}

UXB_RT_API int64_t UXB_RT_CDECL __uxb_rt_runtime_error_exit(const char* message) {
    std::fputs(message ? message : "uXBasic runtime error", stderr);
    std::fputc('\n', stderr);
    std::fflush(stderr);
    std::exit(1);
}

