7	function Find-UxbRoot([string]$start) {
8	    if ([string]::IsNullOrWhiteSpace($start)) { $start=$PSScriptRoot }
9	    $p=(Resolve-Path $start).Path
10	    while ($true) {
11	        if ((Test-Path (Join-Path $p 'src')) -and (Test-Path (Join-Path $p 'native\uxb_runtime'))) { return $p }
12	        $parent=Split-Path $p -Parent
13	        if ($parent -eq $p) { throw 'uXBasic root bulunamadi' }
14	        $p=$parent
15	    }
16	}
17	function First-Command([string[]]$names) {
18	    foreach ($n in $names) {
19	        if ([string]::IsNullOrWhiteSpace($n)) { continue }
20	        if (Test-Path -LiteralPath $n -PathType Leaf) { return (Resolve-Path -LiteralPath $n).Path }
21	        $c=Get-Command $n -ErrorAction SilentlyContinue
22	        if ($c) { return $c.Source }
23	    }
24	    return ''
25	}
26	function Get-PkgFlags([string]$pkgconf,[string]$name) {
27	    if ([string]::IsNullOrWhiteSpace($pkgconf)) { return @() }
28	    & $pkgconf --exists $name 2>$null
29	    if ($LASTEXITCODE -ne 0) { return @() }
30	    $raw=& $pkgconf --cflags --libs $name 2>$null
31	    if ($LASTEXITCODE -ne 0) { return @() }
32	    return (($raw -join ' ') -split '\s+') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
33	}
34	function Pe-Machine([string]$path) {
35	    $b=[IO.File]::ReadAllBytes($path)
36	    if ($b.Length -lt 256) { return 'invalid' }
37	    $o=[BitConverter]::ToInt32($b,0x3c)
38	    $m=[BitConverter]::ToUInt16($b,$o+4)
39	    if ($m -eq 0x8664) { return 'x64' }
40	    if ($m -eq 0x14c) { return 'x86' }
41	    return ('0x{0:X4}' -f $m)
42	}
43	function Resolve-LibuvFlags([string]$pkgconf,[string]$mingwRoot) {
44	    $flags=Get-PkgFlags $pkgconf 'libuv'
45	    if ($flags.Count -gt 0) { return $flags }
46	    $header=Join-Path $mingwRoot 'include\uv.h'
47	    $libdir=Join-Path $mingwRoot 'lib'
48	    if (!(Test-Path $header)) { return @() }
49	    foreach ($name in @('libuv.dll.a','libuv-1.dll.a')) {
50	        $candidate=Join-Path $libdir $name
51	        if (Test-Path $candidate) { return @("-I$($mingwRoot)\include","-L$libdir",$candidate) }
52	    }
53	    return @()
54	}
