Set-Location "C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
$sp = "C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\760ce433-ff72-46c7-8b20-30eed40f7a8c\scratchpad"
# keyword list, copied from lexer_keyword_table.fbs IsKeyword
$src = [System.IO.File]::ReadAllText("src\parser\lexer\lexer_keyword_table.fbs")
$m = [regex]::Match($src, 'Private Function IsKeyword.*?End Select', 'Singleline')
$kw = New-Object System.Collections.Generic.HashSet[string]
foreach ($mm in [regex]::Matches($m.Value, '"([a-z0-9]+)"')) { [void]$kw.Add($mm.Groups[1].Value) }
"keyword count: $($kw.Count)"
$roots = @("tests","libsx","include","examples","game","snippets","docs","libs")
$files = foreach ($r in $roots) { if (Test-Path $r) { [System.IO.Directory]::EnumerateFiles((Resolve-Path $r).Path, "*.*", [System.IO.SearchOption]::AllDirectories) | Where-Object { $_ -match '\.(uxb|bas|uxmh|uxh)$' } } }
"files: $(@($files).Count)"
$hits = New-Object System.Collections.Generic.List[object]
$reDim = [regex]'(?im)^\s*(?:DIM|STATIC|SHARED|CONST|REDIM(?:\s+PRESERVE)?)\s+(?:SHARED\s+)?([A-Za-z_][A-Za-z0-9_]*)'
$reFor = [regex]'(?im)^\s*FOR\s+(?:EACH\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*(?:=|IN\b)'
$reSub = [regex]'(?im)^\s*(?:PUBLIC\s+|PRIVATE\s+|STATIC\s+)?(?:SUB|FUNCTION)\s+([A-Za-z_][A-Za-z0-9_\.]*)\s*\(([^)]*)\)'
foreach ($f in $files) {
  $text = [System.IO.File]::ReadAllText($f)
  foreach ($x in $reDim.Matches($text)) { $n = $x.Groups[1].Value.ToLowerInvariant(); if ($kw.Contains($n)) { $hits.Add([pscustomobject]@{File=$f; Kind='DIM/CONST'; Name=$n}) } }
  foreach ($x in $reFor.Matches($text)) { $n = $x.Groups[1].Value.ToLowerInvariant(); if ($kw.Contains($n)) { $hits.Add([pscustomobject]@{File=$f; Kind='FOR'; Name=$n}) } }
  foreach ($x in $reSub.Matches($text)) {
    $rn = $x.Groups[1].Value.ToLowerInvariant(); if ($kw.Contains($rn)) { $hits.Add([pscustomobject]@{File=$f; Kind='ROUTINE'; Name=$rn}) }
    foreach ($p in ($x.Groups[2].Value -split ',')) { $pm = [regex]::Match($p, '(?i)^\s*(?:BYREF\s+|BYVAL\s+)?([A-Za-z_][A-Za-z0-9_]*)'); if ($pm.Success) { $pn = $pm.Groups[1].Value.ToLowerInvariant(); if ($kw.Contains($pn)) { $hits.Add([pscustomobject]@{File=$f; Kind='PARAM'; Name=$pn}) } } }
  }
}
"hits: $($hits.Count)"
$hits | Group-Object Kind, Name | Sort-Object Count -Descending | Select-Object -First 60 | ForEach-Object { "{0,5}  {1}" -f $_.Count, $_.Name }
$hits | Export-Csv "$sp\kw_scan.csv" -NoTypeInformation -Encoding UTF8

