  "keyword_name_dim_builtin" = @{ src = "' S-128: yerlesik islev adi (LEN) degisken adi olamaz.`nDIM len AS I32`nlen = 7`nPRINT len + 1`n"; msg = "'len' is a reserved uXBasic keyword and cannot be used as a variable name" }
  "keyword_name_dim_statement" = @{ src = "' S-128: deyim sozcugu (COLOR) degisken adi olamaz.`nDIM color AS I32`ncolor = 7`nPRINT color + 1`n"; msg = "'color' is a reserved uXBasic keyword and cannot be used as a variable name" }
  "keyword_name_const" = @{ src = "' S-128: anahtar sozcuk sabit adi olamaz.`nCONST step AS I32 = 3`nPRINT step`n"; msg = "'step' is a reserved uXBasic keyword and cannot be used as a constant name" }
  "keyword_name_param" = @{ src = "' S-128: anahtar sozcuk parametre adi olamaz.`nFUNCTION Twice(abs AS I32) AS I32`n    RETURN abs * 2`nEND FUNCTION`nPRINT Twice(4)`n"; msg = "'abs' is a reserved uXBasic keyword and cannot be used as a parameter name" }
  "keyword_name_for_var" = @{ src = "' S-128: anahtar sozcuk dongu degiskeni adi olamaz.`nDIM total AS I32`nFOR mid = 1 TO 3`n    total += mid`nNEXT mid`nPRINT total`n"; msg = "'mid' is a reserved uXBasic keyword and cannot be used as a loop variable name" }
  "keyword_name_routine" = @{ src = "' S-128: ust duzey SUB/FUNCTION adi anahtar sozcuk olamaz.`nFUNCTION Str(v AS I32) AS I32`n    RETURN v + 1`nEND FUNCTION`nPRINT Str(2)`n"; msg = "'Str' is a reserved uXBasic keyword and cannot be used as a routine name" }
  "keyword_name_type_name" = @{ src = "' S-128: tur adi (F64) degisken adi olamaz.`nDIM f64 AS I32`nPRINT f64`n"; msg = "'f64' is a reserved uXBasic keyword and cannot be used as a variable name" }
}
foreach ($k in $cases.Keys) {
  [System.IO.File]::WriteAllText((Join-Path $dir "$k.uxb"), $cases[$k].src, $enc)
  $lines = @("AST=$($cases[$k].msg)", "MIR=$($cases[$k].msg)", "x64=$($cases[$k].msg)", "AST-x64=$($cases[$k].msg)")
  [System.IO.File]::WriteAllText((Join-Path $dir "expected\$k.contains.txt"), (($lines -join "`r`n") + "`r`n"), $enc)
}
# olumlu: dot ile erisilen uye adlari serbest kalir (S-128 kapsam siniri)
$pos = @'
' S-128: NAMESPACE icindeki rutin adlari anahtar sozcuk olabilir (uxsqlite.Open gibi) ve nokta ile cagrilir.
NAMESPACE lg
    FUNCTION Open(v AS I32) AS I32
        RETURN v + 1
    END FUNCTION
    FUNCTION Close(v AS I32) AS I32
        RETURN v + 2
    END FUNCTION
END NAMESPACE
PRINT lg.Open(1)
PRINT lg.Close(1)
'@
[System.IO.File]::WriteAllText((Join-Path $dir "keyword_name_namespace_member_ok.uxb"), $pos + "`r`n", $enc)
[System.IO.File]::WriteAllText((Join-Path $dir "expected\keyword_name_namespace_member_ok.txt"), "2`r`n3`r`n", $enc)
Get-ChildItem $dir -Filter "keyword_name*" | Select-Object Name | Out-String

