$uxb = ".\bin\uxb_claude1_f64.exe"
$env:UXB_QUIET = "1"
function Clean($t) { ($t | Where-Object { $_ -notmatch '^INFO|^WARN|^\s*$' }) -join "|" }
$prog = "$sp\fprint.uxb"
$r = [ordered]@{}
$r["AST"]    = Clean (& $uxb run $prog 2>&1)
$r["MIR"]    = Clean (& $uxb run $prog --interpreter-backend MIR 2>&1)
foreach ($mode in @("MIR","AST")) {
  $od = "$sp\o_$mode"; if (Test-Path $od) { [System.IO.Directory]::Delete($od, $true) }
  if ($mode -eq "MIR") { & $uxb bld $prog --out-root $od 2>&1 | Out-Null } else { & $uxb bld $prog --x64-mode AST --out-root $od 2>&1 | Out-Null }
  $exe = Get-ChildItem $od -Recurse -Filter program.exe | Select-Object -First 1
  if ($exe) { Push-Location $exe.DirectoryName; $r["x64-$mode"] = Clean (& .\program.exe 2>&1); Pop-Location } else { $r["x64-$mode"] = "BUILDFAIL" }
}
$wd = "$sp\fp_js"; New-Item -ItemType Directory -Force $wd | Out-Null
& $uxb jsw $prog --js-out "$wd\p.js" 2>&1 | Out-Null
$r["JS"] = Clean (node "$wd\p.js" 2>&1)
foreach ($k in $r.Keys) { "== $k`n$($r[$k])" }

