1	[CmdletBinding()]
2	param([string]$Uxb = ".\bin\uxb.exe", [string]$TestRoot = ".\tests\libraries\uxraylib")
3	# uxraylib (raylib/raygui koprusu, CPU-tarafi Image API'si) duman testleri: her program dort motorda (AST, canonical-MIR, native x64, legacy AST-x64)
4	# calistirilir. Beklenen: programin son PRINT'i olan "<AD>_PASS" satiri. CODEPTR kullanan (geri cagirma) testlerde
5	# yorumlayicilar (AST/MIR) gercek kod adresi veremez -> NET "requires native x64" hatasi beklenir (S-076); native ve legacy PASS verir.
6	# Onkosul: bin\uxraylib.dll (+ libraylib.dll, glfw3.dll); runtime_ext\uxraylib\build_wrappers.bat uretir; derleme bagimliliklari PE import tablosundan bulup cikti klasorune kopyalar. Testler PENCERE ACMAZ.
7	$ErrorActionPreference = "Continue"
8	function Norm([string]$s) { (($s -replace "`r","") -split "`n" | Where-Object { $_ -notmatch '^INFO|^WARN|^\s*$' }) -join "`n" }
9	$pass = 0; $fail = 0
10	foreach ($f in Get-ChildItem $TestRoot -Filter *.uxb | Sort-Object Name) {
11	  $src = Get-Content $f.FullName -Raw
12	  $m = [regex]::Match($src, 'PRINT\s+"([A-Z0-9_]+_PASS)"')
13	  if (-not $m.Success) { continue }
14	  $expected = $m.Groups[1].Value
15	  $needsNative = $src -match 'CODEPTR'
16	  $results = [ordered]@{}
17	  $results["AST"] = Norm ((& $Uxb run $f.FullName 2>&1) -join "`n")
18	  $results["MIR"] = Norm ((& $Uxb run $f.FullName --interpreter-backend MIR 2>&1) -join "`n")
19	  foreach ($mode in @(@("x64", @()), @("AST-x64", @("--x64-mode","AST")))) {
20	    $o = (& $Uxb bld $f.FullName @($mode[1]) -o "out\ray_$($mode[0]).exe" 2>&1) -join "`n"
21	    $bm = [regex]::Match($o, "build tamamlandi: (.+)")
22	    $results[$mode[0]] = if ($bm.Success) { Norm ((& $bm.Groups[1].Value.Trim() 2>&1) -join "`n") } else { "BUILDFAIL: " + (Norm $o) }
23	  }
24	  foreach ($k in $results.Keys) {
25	    $interp = ($k -eq "AST" -or $k -eq "MIR")
