1	/* uxraylib raymath core (S-052, raylib Models/3D dilimi 1): CPU-only math support -- no window / GL context needed.
2	 *
3	 * uXBasic's CALL(DLL) carries numbers, not structs, so:
4	 *   - a Vector2/3/4 or Quaternion RESULT is written to a numbered result REGISTER (0..3) and read with
5	 *     uxraylib_res_get(reg, component) (component 0=x 1=y 2=z 3=w). Plain results use register 0; functions with
6	 *     several results (OrthoNormalize, MatrixDecompose) also fill registers 1 and 2;
7	 *   - a Matrix is a HANDLE (small integer, 0 = invalid) into a pool of UX_MAX_MATRICES matrices; every function that
8	 *     produces a matrix returns a NEW handle, released with uxraylib_matrix_release;
9	 *   - a function that would need more than 10 numeric arguments reads its vectors from numbered SLOTS
10	 *     (uxraylib_vector_slot_set) instead.
11	 * An invalid matrix handle behaves as the identity matrix and raises uxraylib_math_last_error() = 1; a full pool
12	 * returns handle 0 and raises 2. The generated part (uxraylib_math.inc) is produced from raymath.h by
13	 * tools/library_tools/gen_uxraylib_math.py.
14	 */
15	#define RAYMATH_IMPLEMENTATION
16	#include <raymath.h>
17	
18	#define UX_MAX_MATRICES 1024
19	#define UX_MATH_REGS 4
20	#define UX_MATH_SLOTS 8
21	static Matrix uxMatrices[UX_MAX_MATRICES];
22	static unsigned char uxMatrixUsed[UX_MAX_MATRICES];
23	static int uxMatrixLive = 0;
24	static double uxMathRegs[UX_MATH_REGS][4];
25	static double uxMathSlots[UX_MATH_SLOTS][4];
26	static int uxMathError = 0;
27	
28	#define V2(a, b) ((Vector2){ (a), (b) })
29	#define V3(a, b, c) ((Vector3){ (a), (b), (c) })
30	#define V4(a, b, c, d) ((Vector4){ (a), (b), (c), (d) })
31	
32	static Matrix uxMatrixGet(int handle)
33	{
34	    if (handle > 0 && handle < UX_MAX_MATRICES && uxMatrixUsed[handle]) return uxMatrices[handle];
35	    uxMathError = 1;
36	    return MatrixIdentity();
37	}
38	
39	static int uxMatrixPut(Matrix m)
40	{
41	    for (int i = 1; i < UX_MAX_MATRICES; ++i) {
42	        if (!uxMatrixUsed[i]) {
43	            uxMatrices[i] = m;
44	            uxMatrixUsed[i] = 1;
45	            uxMatrixLive++;
46	            return i;
47	        }
48	    }
49	    uxMathError = 2;
50	    return 0;
51	}
52	
53	static void uxSetV4(int reg, Vector4 v)
54	{
55	    uxMathRegs[reg][0] = (double)v.x; uxMathRegs[reg][1] = (double)v.y;
56	    uxMathRegs[reg][2] = (double)v.z; uxMathRegs[reg][3] = (double)v.w;
57	}
58	static void uxSetV3(int reg, Vector3 v)
59	{
60	    uxMathRegs[reg][0] = (double)v.x; uxMathRegs[reg][1] = (double)v.y;
61	    uxMathRegs[reg][2] = (double)v.z; uxMathRegs[reg][3] = 0.0;
62	}
63	static void uxSetV2(int reg, Vector2 v)
64	{
65	    uxMathRegs[reg][0] = (double)v.x; uxMathRegs[reg][1] = (double)v.y;
66	    uxMathRegs[reg][2] = 0.0; uxMathRegs[reg][3] = 0.0;
67	}
68	
69	static Vector3 uxSlotV3(int slot)
70	{
71	    if (slot < 0 || slot >= UX_MATH_SLOTS) { uxMathError = 3; slot = 0; }
72	    return (Vector3){ (float)uxMathSlots[slot][0], (float)uxMathSlots[slot][1], (float)uxMathSlots[slot][2] };
73	}
74	static Vector4 uxSlotV4(int slot)
75	{
76	    if (slot < 0 || slot >= UX_MATH_SLOTS) { uxMathError = 3; slot = 0; }
77	    return (Vector4){ (float)uxMathSlots[slot][0], (float)uxMathSlots[slot][1],
78	                      (float)uxMathSlots[slot][2], (float)uxMathSlots[slot][3] };
79	}
80	
81	/* ---- registers, slots, matrix handles ------------------------------------------------------------------------ */
82	UX_EXPORT double uxraylib_res_get(int reg, int component)
83	{
84	    if (reg < 0 || reg >= UX_MATH_REGS || component < 0 || component > 3) return 0.0;
85	    return uxMathRegs[reg][component];
86	}
87	UX_EXPORT double uxraylib_res_x(void) { return uxMathRegs[0][0]; }
88	UX_EXPORT double uxraylib_res_y(void) { return uxMathRegs[0][1]; }
89	UX_EXPORT double uxraylib_res_z(void) { return uxMathRegs[0][2]; }
90	UX_EXPORT double uxraylib_res_w(void) { return uxMathRegs[0][3]; }
91	
92	UX_EXPORT void uxraylib_vector_slot_set(int slot, double x, double y, double z, double w)
93	{
94	    if (slot < 0 || slot >= UX_MATH_SLOTS) { uxMathError = 3; return; }
95	    uxMathSlots[slot][0] = x; uxMathSlots[slot][1] = y; uxMathSlots[slot][2] = z; uxMathSlots[slot][3] = w;
96	}
97	
98	UX_EXPORT int uxraylib_math_last_error(void) { return uxMathError; }
99	UX_EXPORT void uxraylib_math_clear_error(void) { uxMathError = 0; }
100	
101	UX_EXPORT void uxraylib_matrix_release(int handle)
102	{
103	    if (handle > 0 && handle < UX_MAX_MATRICES && uxMatrixUsed[handle]) {
104	        uxMatrixUsed[handle] = 0;
105	        uxMatrixLive--;
106	    }
107	}
108	UX_EXPORT int uxraylib_matrix_live_count(void) { return uxMatrixLive; }
109	UX_EXPORT int uxraylib_matrix_copy(int handle) { return uxMatrixPut(uxMatrixGet(handle)); }
110	
111	/* index 0..15 follows raylib's field order m0 m4 m8 m12 / m1 m5 m9 m13 / m2 m6 m10 m14 / m3 m7 m11 m15:
112	   element (row r, column c) is index c*4 + r. */
113	UX_EXPORT double uxraylib_matrix_element(int handle, int index)
114	{
115	    if (index < 0 || index > 15) return 0.0;
116	    Matrix m = uxMatrixGet(handle);
117	    float cells[16];
118	    memcpy(cells, &m, sizeof(cells));
119	    return (double)cells[index];
120	}
121	UX_EXPORT int uxraylib_matrix_set_element(int handle, int index, double value)
122	{
123	    if (handle <= 0 || handle >= UX_MAX_MATRICES || !uxMatrixUsed[handle]) { uxMathError = 1; return 0; }
124	    if (index < 0 || index > 15) return 0;
125	    float cells[16];
126	    memcpy(cells, &uxMatrices[handle], sizeof(cells));
127	    cells[index] = (float)value;
128	    memcpy(&uxMatrices[handle], cells, sizeof(cells));
129	    return 1;
130	}
131	
132	/* ---- functions the generator cannot express (pointers / structs / more than 10 arguments) -------------------- */
133	/* Vector3OrthoNormalize: results in register 0 (v1) and register 1 (v2). */
134	UX_EXPORT void uxraylib_vector3_ortho_normalize(double v1x, double v1y, double v1z, double v2x, double v2y, double v2z)
135	{
136	    Vector3 a = V3((float)v1x, (float)v1y, (float)v1z);
137	    Vector3 b = V3((float)v2x, (float)v2y, (float)v2z);
138	    Vector3OrthoNormalize(&a, &b);
139	    uxSetV3(0, a);
140	    uxSetV3(1, b);
141	}
142	
143	/* QuaternionToAxisAngle: returns the angle (radians); the axis is in register 0. */
144	UX_EXPORT double uxraylib_quaternion_to_axis_angle(double qx, double qy, double qz, double qw)
145	{
146	    Vector3 axis = { 0.0f, 0.0f, 0.0f };
147	    float angle = 0.0f;
148	    QuaternionToAxisAngle(V4((float)qx, (float)qy, (float)qz, (float)qw), &axis, &angle);
149	    uxSetV3(0, axis);
150	    return (double)angle;
151	}
152	
153	/* MatrixDecompose: register 0 = translation, register 1 = rotation quaternion, register 2 = scale. */
154	UX_EXPORT void uxraylib_matrix_decompose(int handle)
155	{
156	    Vector3 translation, scale;
157	    Quaternion rotation;
158	    MatrixDecompose(uxMatrixGet(handle), &translation, &rotation, &scale);
159	    uxSetV3(0, translation);
160	    uxSetV4(1, rotation);
161	    uxSetV3(2, scale);
162	}
163	
164	/* slot variants of the functions that exceed the 10-argument CALL(DLL) limit */
165	UX_EXPORT void uxraylib_vector3_cubic_hermite_slots(int v1, int tangent1, int v2, int tangent2, double amount)
166	{
167	    uxSetV3(0, Vector3CubicHermite(uxSlotV3(v1), uxSlotV3(tangent1), uxSlotV3(v2), uxSlotV3(tangent2), (float)amount));
168	}
169	UX_EXPORT void uxraylib_vector3_barycenter_slots(int p, int a, int b, int c)
170	{
171	    uxSetV3(0, Vector3Barycenter(uxSlotV3(p), uxSlotV3(a), uxSlotV3(b), uxSlotV3(c)));
172	}
173	UX_EXPORT void uxraylib_quaternion_cubic_hermite_spline_slots(int q1, int outTangent1, int q2, int inTangent2, double t)
174	{
175	    uxSetV4(0, QuaternionCubicHermiteSpline(uxSlotV4(q1), uxSlotV4(outTangent1), uxSlotV4(q2), uxSlotV4(inTangent2), (float)t));
176	}
177	
178	#include "uxraylib_math.inc"

