342	    return 0;
343	}
344	
345	static HMODULE uxb_load_library_for_program(const char* dll_name) {
346	    HMODULE h = LoadLibraryA(dll_name);
347	    if (h) return h;
348	    if (!dll_name || !dll_name[0] || uxb_is_absolute_dll_path(dll_name)) return NULL;
349	    char module_path[MAX_PATH];
350	    DWORD n = GetModuleFileNameA(NULL, module_path, MAX_PATH);
351	    if (n == 0 || n >= MAX_PATH) return NULL;
352	    char* tail = module_path + strlen(module_path);
353	    while (tail > module_path && tail[-1] != '\\' && tail[-1] != '/') --tail;
354	    *tail = '\0';
355	    size_t dir_len = strlen(module_path);
356	    size_t dll_len = strlen(dll_name);
357	    if (dir_len + 1 + dll_len + 1 > MAX_PATH) return NULL;
358	    char full_path[MAX_PATH];
359	    memcpy(full_path, module_path, dir_len);
360	    full_path[dir_len] = '\\';
361	    memcpy(full_path + dir_len + 1, dll_name, dll_len + 1);
362	    return LoadLibraryA(full_path);
363	}
