static int uxb_is_absolute_dll_path(const char* path) {
    if (!path || !path[0]) return 0;
    if ((path[0] == '\\' && path[1] == '\\') || path[0] == '/') return 1;
    if (((path[0] >= 'A' && path[0] <= 'Z') || (path[0] >= 'a' && path[0] <= 'z')) && path[1] == ':') return 1;
    return 0;
}

static HMODULE uxb_load_library_for_program(const char* dll_name) {
    HMODULE h = LoadLibraryA(dll_name);
    if (h) return h;
    if (!dll_name || !dll_name[0] || uxb_is_absolute_dll_path(dll_name)) return NULL;
    char module_path[MAX_PATH];
    DWORD n = GetModuleFileNameA(NULL, module_path, MAX_PATH);
    if (n == 0 || n >= MAX_PATH) return NULL;
    char* tail = module_path + strlen(module_path);
    while (tail > module_path && tail[-1] != '\\' && tail[-1] != '/') --tail;
    *tail = '\0';
    size_t dir_len = strlen(module_path);
    size_t dll_len = strlen(dll_name);
    if (dir_len + 1 + dll_len + 1 > MAX_PATH) return NULL;
    char full_path[MAX_PATH];
    memcpy(full_path, module_path, dir_len);
    full_path[dir_len] = '\\';
    memcpy(full_path + dir_len + 1, dll_name, dll_len + 1);
    return LoadLibraryA(full_path);
}

static void uxb_resolve_fail(const char* op, const char* dll_name, const char* symbol_name) {
    fprintf(stderr, "uXBasic x64 FFI resolve failed: %s dll=%s symbol=%s\n", op ? op : "?", dll_name ? dll_name : "?", symbol_name ? symbol_name : "?");
    fflush(stderr);
    ExitProcess(127);
}

static void uxb_resolve_one(void** target, const char* dll_name, const char* symbol_name) {
    if (!target || *target) return;
    HMODULE h = uxb_load_library_for_program(dll_name);
    if (!h) uxb_resolve_fail("LoadLibraryA", dll_name, symbol_name);
    FARPROC proc = GetProcAddress(h, symbol_name);
    if (!proc) uxb_resolve_fail("GetProcAddress", dll_name, symbol_name);
    *target = (void*)proc;
}

