Set-Location "C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
$env:UXB_QUIET = "1"
$uxb = ".\bin\uxb_claude1_s179.exe"
function Clean($t) { ($t | Where-Object { $_ -notmatch '^INFO|^WARN|^\s*$' }) -join "|" }
$f = "tests\language_guards\val_returns_double.uxb"
"AST : " + (Clean (& $uxb run $f 2>&1))
"MIR : " + (Clean (& $uxb run $f --interpreter-backend MIR 2>&1))
foreach ($mode in @(@("x64",@()), @("AST-x64",@("--x64-mode","AST")))) {
  $out = & $uxb bld $f @($mode[1]) 2>&1
  $m = [regex]::Match(($out -join "`n"), "build tamamlandi: (.+)")
  if ($m.Success) { $exe=$m.Groups[1].Value.Trim(); Push-Location (Split-Path $exe); "$($mode[0]) : " + (Clean (& .\program.exe 2>&1)); Pop-Location }
  else { "$($mode[0]) BUILDFAIL: " + (Clean ($out -join "`n")) }
}

